// One home for screen artwork. Paths are relative to dist/ (the web root).
window.PeninsulaScreenAssets=Object.freeze({
 root:'assets/screens/',
 layout:key=>'assets/screens/layouts/'+key+'-bg.png',
 introVideo:'assets/screens/intros/',
 intro5:'assets/screens/intro5-full.png',
 victory:'assets/screens/victory1/fish-pickup-frames.png',
 // full-game's asset loader adds the assets/ prefix and .png extension.
 asset:path=>'screens/'+path
});
